1: import React from "react";
2: 
3: import {
4:   Button,
5:   Center,
6:   Dialog,
7:   PageAnnouncementProvider,
8:   Spinner,
9:   Text,
10: } from "@mtfh/common/lib/components";
11: import { useErrorCodes } from "@mtfh/common/lib/hooks";
12: import { ContactDetailsView } from "@mtfh/personal-details";
13: import "./styles.scss";
14: 
15: export const ContactDetailsUpdateDialog = ({ isDialogOpen, setDialogOpen, personId }) => {
16:   const errorMessages = useErrorCodes();
17: 
18:   if (!errorMessages) {
19:     return (
20:       <Center>
21:         <Spinner />
22:       </Center>
23:     );
24:   }
25: 
26:   const close = () => setDialogOpen(false);
27: 
28:   return (
29:     <Dialog
30:       isOpen={isDialogOpen}
31:       onDismiss={close}
32:       title="Update contact details"
33:       className="lbh-dialog-contact-details"
34:     >
35:       <Text size="sm">
36:         The details will be instantly updated within MMH when you save the email
37:         address/phone number.
38:       </Text>
39:       <Text size="sm">
40:         Only the first phone and email address will be displayed within the MMH
41:         application e.g. for appointment bookings.
42:       </Text>
43:       <Text size="sm">
44:         You can 'Return to your application' once you have completed the updates. The new
45:         contact details will be displayed.
46:       </Text>
47:       <PageAnnouncementProvider sessionKey="editPerson">
48:         <ContactDetailsView
49:           providedPersonId={personId}
50:           onComplete={(_, hasUpdatedContactDetails: boolean) => {
51:             if (hasUpdatedContactDetails) {
52:               sessionStorage.setItem("person:heading", "Person Updated");
53:             }
54:           }}
55:           hideAddress
56:           isInADialog
57:         />
58:       </PageAnnouncementProvider>
59:       <Button
60:         data-testid="close-update-contact-details-modal"
61:         variant="primary"
62:         onClick={close}
63:       >
64:         Return to application
65:       </Button>
66:     </Dialog>
67:   );
68: };
